create table if not exists automations (id bigserial primary key, organization_id uuid not null references organizations(id), name text not null, trigger text not null check(trigger in ('lead_created','task_overdue','receivable_overdue','ticket_created')), action text not null check(action in ('notify','create_task','send_message')), config jsonb not null default '{}', active boolean default true, runs int default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists templates (id bigserial primary key, organization_id uuid not null references organizations(id), kind text check(kind in ('proposal','email','message')), name text not null, body text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists integrations (id bigserial primary key, organization_id uuid not null references organizations(id), provider text not null check(provider in ('whatsapp','email','google_calendar','webhook')), status text not null default 'disconnected' check(status in ('disconnected','connected')), config jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,provider));
create index if not exists automations_organization_id_idx on automations(organization_id);
create index if not exists templates_organization_id_idx on templates(organization_id);
create index if not exists integrations_organization_id_idx on integrations(organization_id);
